package au.aumanet.app;
import java.nio.*;import java.security.*;import java.security.spec.*;import java.util.*;import org.json.*;

/** Test-only ephemeral keys; no Android or radio dependency. */
public final class GatewayRadioSettingsTest {
 static int assertions,tests;static final String A="1".repeat(32),B="2".repeat(32),GROUP="3".repeat(32),RUN="4".repeat(32),BRUN="5".repeat(32),OWNER="A".repeat(64),Q="B".repeat(64),TX="6".repeat(32);
 interface Work{void run()throws Exception;}static void check(boolean b){assertions++;if(!b)throw new AssertionError("Radio policy regression");}static void rejects(Work w)throws Exception{boolean denied=false;try{w.run();}catch(Exception expected){denied=true;}check(denied);}
 static GatewayRadioConfigCodec.Message report(boolean station,String run,int state,int actual,int persisted,long generation,String tx)throws Exception{byte[] q=GatewayRadioConfigCodec.query(station?B:A,GROUP,1,OWNER,A,Q).body(),r=Arrays.copyOf(q,232);r[5]='R';System.arraycopy(GatewayGrantCodec.identifier(run),0,r,136,16);Arrays.fill(r,152,184,(byte)17);System.arraycopy(GatewayBootCodec.bytes(tx.toUpperCase(Locale.ROOT),16),0,r,184,16);ByteBuffer.wrap(r).putLong(200,generation);r[208]=(byte)actual;r[209]=(byte)persisted;r[210]=(byte)(state==3?actual:0);r[211]=(byte)state;ByteBuffer.wrap(r).putInt(212,state==3?20000:0);r[216]=(byte)actual;r[217]=1;r[218]=(byte)(station?1:0);r[219]=(byte)(station?0:3);ByteBuffer.wrap(r).putShort(222,(short)1);r[224]=24;return GatewayRadioConfigCodec.parse(r);}
 static void codec()throws Exception{tests++;check(GatewayRadioConfigCodec.options().length()==23);check(GatewayRadioConfigCodec.option(5).getInt("channel")==36);check(GatewayRadioConfigCodec.option(22).getInt("bandwidthMHz")==8);for(int i=1;i<=23;i++)check(GatewayRadioConfigCodec.option(i).getInt("id")==i);rejects(()->GatewayRadioConfigCodec.option(0));GatewayRadioConfigCodec.Message r=report(false,RUN,0,5,5,0,"0".repeat(32));check(r.generation==0&&r.actual==5&&r.power==24);byte[] bad=r.body();bad[225]=1;final byte[] reserved=bad;rejects(()->GatewayRadioConfigCodec.parse(reserved));bad=r.body();bad[224]=25;final byte[] power=bad;rejects(()->GatewayRadioConfigCodec.parse(power));bad=r.body();bad[216]=24;final byte[] option=bad;rejects(()->GatewayRadioConfigCodec.parse(option));bad=r.body();bad[218]=1;final byte[] role=bad;rejects(()->GatewayRadioConfigCodec.parse(role));GatewayRadioConfigCodec.Message c=GatewayRadioConfigCodec.command(r,TX,1,22);check(c.kind=='C'&&c.trial==22&&c.generation==0&&c.run.equals(RUN));rejects(()->GatewayRadioConfigCodec.command(report(true,BRUN,0,5,0,0,"0".repeat(32)),TX,1,22));}
 static void signatures()throws Exception{tests++;KeyPairGenerator gen=KeyPairGenerator.getInstance("EC");gen.initialize(new ECGenParameterSpec("secp256r1"));KeyPair pair=gen.generateKeyPair(),wrong=gen.generateKeyPair();GatewayRadioConfigCodec.Message r=report(false,RUN,0,5,5,0,"0".repeat(32));Signature sign=Signature.getInstance("SHA256withECDSA");sign.initSign(pair.getPrivate());sign.update(r.body());byte[] frame=GatewayRadioConfigCodec.envelope(r,sign.sign());check(GatewayRadioConfigCodec.frame(frame,frame.length).verify(pair.getPublic()));check(!GatewayRadioConfigCodec.frame(frame,frame.length).verify(wrong.getPublic()));byte[] mutated=frame.clone();mutated[16+216]=6;check(!GatewayRadioConfigCodec.frame(mutated,mutated.length).verify(pair.getPublic()));mutated=frame.clone();mutated[0]^=1;final byte[] target=mutated;rejects(()->GatewayRadioConfigCodec.frame(target,target.length));rejects(()->GatewayRadioConfigCodec.frame(frame,frame.length-1));byte[] p256sign=new byte[]{0x30,6,2,1,0,2,1,1};rejects(()->GatewayRadioConfigCodec.envelope(r,p256sign));check(GatewayRadioConfigCodec.sameCommon(r,GatewayRadioConfigCodec.query(A,GROUP,1,OWNER,A,Q)));check(!GatewayRadioConfigCodec.sameCommon(r,GatewayRadioConfigCodec.query(A,GROUP,2,OWNER,A,Q)));}
 static void commitTruth()throws Exception{tests++;GatewayRadioConfigCodec.Message a=report(false,RUN,0,5,5,7,"0".repeat(32)),b=report(true,BRUN,0,5,0,0,"0".repeat(32));rejects(()->new GatewayRadioChange(TX,5,a,b));GatewayRadioChange change=new GatewayRadioChange(TX,22,a,b);GatewayRadioConfigCodec.Message at=report(false,RUN,3,22,5,7,TX),bt=report(true,BRUN,0,22,0,0,"0".repeat(32));check(change.targetSeen(at,bt));check(!change.committed(at,bt));check(!change.targetSeen(at,b));check(!change.targetSeen(report(false,"7".repeat(32),3,22,5,7,TX),bt));check(!change.targetSeen(report(false,RUN,3,22,5,7,"8".repeat(32)),bt));GatewayRadioConfigCodec.Message done=report(false,RUN,0,22,22,8,TX);check(change.committed(done,bt));check(!change.committed(report(false,RUN,0,22,22,7,TX),bt));check(!change.committed(done,b));byte[] changedPower=bt.body();changedPower[224]=14;check(!change.committed(done,GatewayRadioConfigCodec.parse(changedPower)));rejects(()->new GatewayRadioChange(TX,22,report(false,RUN,0,5,5,GroupNamePolicy.MAX_REVISION,"0".repeat(32)),b));}
 static void ages()throws Exception{tests++;JSONObject ap=GroupRadioConfiguration.report(report(false,RUN,0,5,5,0,"0".repeat(32)),100);JSONArray original=new JSONArray().put(ap);JSONArray received=GroupRadioConfiguration.merge(new JSONArray(),0,original,200);check(received.getJSONObject(0).getLong("observedElapsedMs")==200);JSONArray again=GroupRadioConfiguration.merge(received,4000,original,4200);check(again.getJSONObject(0).getLong("reportAgeMs")==4000);JSONArray aged=GroupRadioConfiguration.age(again,1000,5200);check(aged.getJSONObject(0).getLong("reportAgeMs")==5000);check(!aged.getJSONObject(0).has("rssiDbm"));check(GroupRadioConfiguration.age(aged,-1,0).length()==0);rejects(()->GroupRadioConfiguration.checked(new JSONArray().put(ap).put(ap),0,"owner-relayed"));JSONObject malformed=new JSONObject(ap.toString()).put("configuredTxPowerDbm",24.5);rejects(()->GroupRadioConfiguration.checked(new JSONArray().put(malformed),0,"pinned-node"));JSONObject next=new JSONObject(ap.toString()).put("observationId","C".repeat(64));JSONArray changed=GroupRadioConfiguration.merge(again,5000,new JSONArray().put(next),9200);check(changed.getJSONObject(0).getLong("reportAgeMs")==0);}
 static void diagnostics(){tests++;GatewayRadioQueryTrace t=new GatewayRadioQueryTrace(false,0);t.stage=GatewayRadioQueryTrace.Stage.WAIT;t.failure=GatewayRadioQueryTrace.Failure.DEADLINE;check(t.line(2000).contains("role=AP action=QUERY stage=WAIT reason=NO_REPLY"));t.packets=1;t.malformed=1;check(t.line(2000).contains("reason=MALFORMED_REPORT"));t.wrongCommon=1;check(t.line(2000).contains("reason=UNMATCHED_REPORT"));t.wrongPurpose=1;check(t.line(2000).contains("reason=WRONG_PURPOSE"));t.badSignature=1;check(t.line(2000).contains("reason=SIGNATURE_REJECTED"));t.failure=GatewayRadioQueryTrace.Failure.SCOPE_CHANGED;t.stage=GatewayRadioQueryTrace.Stage.BOOT;t.wrongBoot=1;check(t.line(5).contains("stage=BOOT reason=SCOPE_CHANGED"));check(t.line(5).contains("wrongBoot=1"));t.packets=Integer.MAX_VALUE;check(t.line(Long.MAX_VALUE).contains("packets=9999"));check(t.line(Long.MAX_VALUE).contains("elapsedMs=60000"));String line=t.line(-1);check(line.contains("elapsedMs=0")&&line.length()<300);check(!line.contains(OWNER)&&!line.contains(GROUP)&&!line.contains(Q));}
 public static void main(String[] args)throws Exception{diagnostics();codec();signatures();commitTruth();ages();System.out.println(new JSONObject().put("status","pass").put("testCount",tests).put("assertionCount",assertions));}
}

